import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int twoPow = 23;
    private static final int ROOT = 15311432;

    private static int reverseBits(int n, int k) {
        int result = 0;
        for (int i = 0; i < k; i++) {
            result = (result << 1) | (n & 1);
            n >>= 1;
        }
        return result;
    }

    private static long fastPow(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modularInverse(long a) {
        return fastPow(a, MOD - 2);
    }

    private static long[] computeRoots(int k, boolean inverse) {
        long root = fastPow(ROOT, fastPow(2, twoPow - k));
        if (inverse) {
            root = modularInverse(root);
        }
        long[] roots = new long[k];
        if (k > 0) {
            roots[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

    private static long[] reorder(long[] array, int k) {
        long[] result = new long[array.length];
        for (int i = 0; i < array.length; i++) {
            result[reverseBits(i, k)] = array[i];
        }
        return result;
    }

    private static long[] nttTransform(long[] coef, int k, boolean inverse) {
        coef = reorder(coef, k);
        long[] roots = computeRoots(k, inverse);
        for (int s = 0; s < k; s++) {
            int segmentLength = 1 << s;
            for (int start = 0; start < coef.length; start += 2 * segmentLength) {
                long currentRoot = 1;
                for (int j = start; j < start + segmentLength; j++) {
                    long t = (currentRoot * coef[j + segmentLength]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + segmentLength] = (u - t + MOD) % MOD;
                    currentRoot = (roots[s] * currentRoot) % MOD;
                }
            }
        }
        return coef;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        int maxVal = 0;
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
            maxVal = Math.max(maxVal, nums[i]);
        }
        int minSize = n * maxVal + 1;
        int size = 1;
        int k = 0;
        while (size < minSize) {
            size <<= 1;
            k++;
        }
        long[] array = new long[size];
        for (int i = 0; i < nums.length; i++) {
            array[nums[i]] = 1;
        }
        array = nttTransform(array, k, false);
        for (int i = 0; i < size; i++) {
            array[i] = modPow(array[i], n);
        }
        array = nttTransform(array, k, true);
        long total = 0;
        for (int i = 0; i < size; i++) {
            total = (total + array[i] * array[i]) % MOD;
        }
        long invSize = modularInverse(size);
        System.out.println((((total * invSize) % MOD) * invSize) % MOD);
    }
}
